afG(a){return""+a+" \u0628\u0627\u0646\u062a\u0638\u0627\u0631\u0643"},
ag3(a){return""+a+" \u0623\u0633\u0637\u0631 \u0628\u062d\u0627\u062c\u0629 \u0625\u0644\u064a\u0643"},
gafV(){return"\u062a\u0639\u0630\u0651\u0631\u062a \u0642\u0631\u0627\u0621\u062a\u0647\u0627 \u0628\u0648\u0636\u0648\u062d"},
gafR(){return"\u0647\u0630\u0647 \u0627\u0644\u0642\u064a\u0645\u0629 \u062e\u0627\u0631\u062c \u0627\u0644\u0645\u062f\u0649 \u0627\u0644\u0645\u0645\u0643\u0646 \u0644\u0647\u0630\u0627 \u0627\u0644\u0641\u062d\u0635"},
gafU(){return"\u0647\u0630\u0647 \u0627\u0644\u0648\u062d\u062f\u0629 \u063a\u064a\u0631 \u0645\u0639\u0631\u0648\u0641\u0629 \u0644\u0647\u0630\u0627 \u0627\u0644\u0641\u062d\u0635"},
gafT(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0648\u062d\u062f\u0629 \u0645\u0637\u0628\u0648\u0639\u0629 \u0628\u062c\u0627\u0646\u0628 \u0647\u0630\u0647 \u0627\u0644\u0642\u064a\u0645\u0629"},
gafP(){return"\u0647\u0630\u0647 \u0627\u0644\u0642\u064a\u0645\u0629 \u062a\u0646\u0627\u0642\u0636 \u0642\u064a\u0645\u0629 \u0623\u062e\u0631\u0649 \u0641\u064a \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0646\u0641\u0633\u0647"},
gI4(){return"\u0645\u0627 \u0647\u0630\u0627 \u0627\u0644\u0641\u062d\u0635\u061f"},
gafO(){return"\u0647\u0630\u0627 \u0644\u064a\u0633 \u0631\u0642\u0645\u0627\u064b \u0648\u0627\u0636\u062d\u0627\u064b"},
gafQ(){return"\u0647\u0630\u0647 \u0627\u0644\u0642\u064a\u0645\u0629 \u0645\u0648\u062c\u0648\u062f\u0629 \u0644\u062f\u064a\u0643 \u0645\u0633\u0628\u0642\u0627\u064b"},
gTy(){return"\u062a\u0639\u0630\u0651\u0631\u062a \u0642\u0631\u0627\u0621\u0629 \u0647\u0630\u0627 \u0627\u0644\u0645\u0633\u062a\u0646\u062f"},
gafu(){return"\u0644\u0645 \u0646\u0642\u0631\u0623 \u0625\u062d\u062f\u0649 \u0627\u0644\u0642\u064a\u0645 \u0628\u062b\u0642\u0629 \u0643\u0627\u0641\u064a\u0629 \u0644\u0625\u0636\u0627\u0641\u062a\u0647\u0627 \u0643\u0645\u0627 \u0647\u064a. \u0627\u0643\u062a\u0628\u0647\u0627 \u0628\u0646\u0641\u0633\u0643 \u0643\u0645\u0627 \u062a\u0631\u0627\u0647\u0627 \u0641\u064a \u0627\u0644\u0648\u0631\u0642\u0629\u060c \u062b\u0645 \u0627\u0636\u063a\u0637 \u2713 \u0639\u0644\u0649 \u0633\u0637\u0631\u0647\u0627."},
gafv(){return"\u0639\u0644\u0649 \u0625\u062d\u062f\u0649 \u0627\u0644\u0642\u064a\u0645 \u0645\u0644\u0627\u062d\u0638\u0629 \u062a\u0645\u0646\u0639 \u0642\u0628\u0648\u0644\u0647\u0627 \u0643\u0645\u0627 \u0642\u0631\u0623\u0646\u0627\u0647\u0627. \u0627\u0643\u062a\u0628\u0647\u0627 \u0628\u0646\u0641\u0633\u0643 \u0645\u0646 \u0627\u0644\u0648\u0631\u0642\u0629\u060c \u0623\u0648 \u0623\u0632\u0644 \u0633\u0637\u0631\u0647\u0627."},
gafp(){return"\u0627\u0644\u0642\u064a\u0645\u0629 \u062e\u0627\u0631\u062c \u0627\u0644\u0645\u062f\u0649 \u0627\u0644\u0637\u0628\u064a\u0639\u064a \u0644\u0627 \u062a\u064f\u0636\u0627\u0641 \u0636\u0645\u0646 \u0642\u0628\u0648\u0644 \u062c\u0645\u0627\u0639\u064a \u2014 \u0623\u0643\u0651\u062f\u0647\u0627 \u0628\u0646\u0641\u0633\u0643 \u0639\u0644\u0649 \u0633\u0637\u0631\u0647\u0627."},
gafs(){return"\u0628\u0642\u064a \u0633\u0637\u0631 \u0644\u0645 \u062a\u0642\u0631\u0651\u0631 \u0628\u0634\u0623\u0646\u0647. \u0623\u0643\u0651\u062f \u0643\u0644 \u0633\u0637\u0631 \u0623\u0648 \u0623\u0632\u0644\u0647\u060c \u062b\u0645 \u0623\u0639\u062f \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629."},
gafz(){return"\u0645\u0627 \u0643\u064f\u062a\u0628 \u0641\u064a \u0623\u062d\u062f \u0627\u0644\u062d\u0642\u0648\u0644 \u0644\u064a\u0633 \u0631\u0642\u0645\u0627\u064b \u0646\u0633\u062a\u0637\u064a\u0639 \u062d\u0641\u0638\u0647. \u0631\u0627\u062c\u0639\u0647 \u0648\u0623\u0639\u062f \u0643\u062a\u0627\u0628\u062a\u0647."},
gafy(){return"\u0623\u062d\u062f \u0627\u0644\u0633\u0637\u0648\u0631 \u0628\u0644\u0627 \u0642\u064a\u0645\u0629. \u0627\u0643\u062a\u0628 \u0627\u0644\u0642\u064a\u0645\u0629 \u0643\u0645\u0627 \u062a\u0631\u0627\u0647\u0627 \u0641\u064a \u0627\u0644\u0648\u0631\u0642\u0629\u060c \u0623\u0648 \u0623\u0632\u0644 \u0627\u0644\u0633\u0637\u0631."},
gafx(){return"\u0623\u062d\u062f \u0627\u0644\u0633\u0637\u0648\u0631 \u0628\u0644\u0627 \u0641\u062d\u0635 \u0645\u062d\u062f\u064e\u0651\u062f. \u0627\u062e\u062a\u0631 \u0627\u0633\u0645 \u0627\u0644\u0641\u062d\u0635\u060c \u0623\u0648 \u0623\u0632\u0644 \u0627\u0644\u0633\u0637\u0631."},
gafr(){return"\u0625\u062d\u062f\u0649 \u0627\u0644\u0642\u064a\u0645 \u062e\u0627\u0631\u062c \u0627\u0644\u0645\u062f\u0649 \u0627\u0644\u0645\u0645\u0643\u0646 \u0644\u0647\u0630\u0627 \u0627\u0644\u0641\u062d\u0635 \u2014 \u0627\u0644\u0623\u0631\u062c\u062d \u0623\u0646\u0647\u0627 \u0642\u0631\u0627\u0621\u0629 \u062e\u0627\u0637\u0626\u0629. \u0631\u0627\u062c\u0639\u0647\u0627 \u0639\u0644\u0649 \u0627\u0644\u0648\u0631\u0642\u0629."},
gaft(){return"\xab\u0637\u0628\u064a\u0639\u064a\xbb \u0648\xab\u063a\u064a\u0631 \u0637\u0628\u064a\u0639\u064a\xbb \u062d\u0643\u0645 \u0648\u0644\u064a\u0633 \u0646\u062a\u064a\u062c\u0629 \u0645\u0637\u0628\u0648\u0639\u0629. \u0627\u0643\u062a\u0628 \u0627\u0644\u0646\u062a\u064a\u062c\u0629 \u0643\u0645\u0627 \u0647\u064a \u0645\u0637\u0628\u0648\u0639\u0629 \u0641\u064a \u0627\u0644\u0648\u0631\u0642\u0629."},
gafq(){return"\u062d\u064f\u0630\u0641 \u0627\u0644\u0645\u0633\u062a\u0646\u062f \u0627\u0644\u0630\u064a \u062c\u0627\u0621\u062a \u0645\u0646\u0647 \u0647\u0630\u0647 \u0627\u0644\u0642\u064a\u0645\u060c \u0641\u0644\u0627 \u064a\u0645\u0643\u0646 \u0625\u0636\u0627\u0641\u062a\u0647\u0627 \u0625\u0644\u0649 \u0633\u062c\u0644\u0651\u0643."},
gafw(){return"\u0623\u064f\u0636\u064a\u0641\u062a \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629 \u0645\u0633\u0628\u0642\u0627\u064b \u0623\u0648 \u0644\u0645 \u062a\u0639\u062f \u0645\u062a\u0627\u062d\u0629. \u0623\u0639\u062f \u0641\u062a\u062d \u0627\u0644\u0634\u0627\u0634\u0629."},
gagf(){return"\u0623\u064f\u0636\u064a\u0641\u062a \u0627\u0644\u0642\u064a\u0645 \u0625\u0644\u0649 \u0633\u062c\u0644\u0651\u0643"},
gage(){return"\u0623\u064f\u062e\u0641\u064a\u062a \u0627\u0644\u0642\u064a\u0645\u0629 \u0645\u0646 \u0633\u062c\u0644\u0651\u0643 \u2014 \u0644\u0645 \u062a\u064f\u062d\u0630\u0641\u060c \u0648\u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u0639\u0627\u062f\u062a\u0647\u0627 \u0644\u0627\u062d\u0642\u0627\u064b"},
gagd(){return"\u0623\u064f\u062e\u0641\u064a \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0645\u0646 \u0633\u062c\u0644\u0651\u0643 \u2014 \u0644\u0645 \u064a\u064f\u062d\u0630\u0641\u060c \u0648\u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u0639\u0627\u062f\u062a\u0647 \u0644\u0627\u062d\u0642\u0627\u064b"},
agc(a){return"\u0631\u0645\u0632 \u0627\u0644\u062e\u0637\u0623: "+a},
