gKa(){return"\u0623\u0635\u062d\u0651\u062d"},
gXw(){return"\u0644\u0627 \u0623\u0633\u062a\u0637\u064a\u0639 \u0627\u0644\u062a\u0623\u0643\u064a\u062f"},
