gafa(){return"\u0626\u06cc\u0645\u06d5\u06cc\u06b5 \u06cc\u0627\u0646 \u0648\u0634\u06d5\u06cc \u062a\u06ce\u067e\u06d5\u0695\u0628\u0648\u0648\u0646 \u062f\u0631\u0648\u0633\u062a \u0646\u06cc\u06cc\u06d5."},
ga_7(){return"\u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u062f\u0646\u06cc \u0647\u06d5\u0698\u0645\u0627\u0631\u06ce\u06a9\u06cc \u0646\u0648\u06ce"},
ga_6(){return"\u06cc\u06d5\u06a9 \u0695\u06ce\u06af\u0627 \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u06d5. \u067e\u0627\u0634\u0627\u0646 \u067e\u0695\u06c6\u0641\u0627\u06cc\u0644\u06d5\u06a9\u06d5\u062a \u062a\u06d5\u0648\u0627\u0648 \u062f\u06d5\u06a9\u06d5\u06cc\u0646: \u0646\u0627\u0648\u060c \u062a\u06d5\u0644\u06d5\u0641\u06c6\u0646\u060c \u062c\u06c6\u0631\u06cc \u062e\u0648\u06ce\u0646."},
ga_0(){return"\u0628\u06af\u06d5\u0695\u06ce\u0648\u06d5 \u0646\u0627\u0648 \u062a\u06c6\u0645\u0627\u0631\u06d5 \u0647\u06d5\u06cc\u06d5\u06a9\u06d5\u062a."},
ga_8(){return"\u0647\u06d5\u0698\u0645\u0627\u0631 \u0628\u06d5 \u0626\u06cc\u0645\u06d5\u06cc\u06b5 \u0648 \u0648\u0634\u06d5\u06cc \u062a\u06ce\u067e\u06d5\u0695\u0628\u0648\u0648\u0646"},
ga_5(){return"\u0647\u06d5\u0698\u0645\u0627\u0631\u0645 \u0647\u06d5\u06cc\u06d5 \u2014 \u0686\u0648\u0648\u0646\u06d5\u0698\u0648\u0648\u0631\u06d5\u0648\u06d5"},
gZZ(){return"\u0647\u06d5\u0698\u0645\u0627\u0631\u0645 \u0646\u06cc\u06cc\u06d5 \u2014 \u06cc\u06d5\u06a9\u06ce\u06a9 \u062f\u0631\u0648\u0633\u062a \u0628\u06a9\u06d5"},
gake(){return"\u0647\u06cc\u0686 \u062a\u06c6\u0645\u0627\u0631\u06ce\u06a9\u0645\u0627\u0646 \u0628\u06c6 \u0626\u06d5\u0645 \u0647\u06d5\u0698\u0645\u0627\u0631\u06d5 \u0646\u06d5\u062f\u06c6\u0632\u06cc\u06cc\u06d5\u0648\u06d5"},
gakb(){return"\u0628\u06d5 \u0633\u06d5\u0631\u06a9\u06d5\u0648\u062a\u0648\u0648\u06cc\u06cc \u0686\u0648\u0648\u06cc\u062a\u06d5 \u0698\u0648\u0648\u0631\u06d5\u0648\u06d5\u060c \u0628\u06d5\u06b5\u0627\u0645 \u0647\u06cc\u0686 \u067e\u0695\u06c6\u0641\u0627\u06cc\u0644\u06ce\u06a9 \u0628\u06d5\u0645 \u0647\u06d5\u0698\u0645\u0627\u0631\u06d5\u0648\u06d5 \u0646\u06d5\u0628\u06d5\u0633\u062a\u0631\u0627\u0648\u06d5. \u0626\u06d5\u06af\u06d5\u0631 \u062a\u06c6\u0645\u0627\u0631\u06ce\u06a9\u06cc \u067e\u06ce\u0634\u0648\u0648\u062a \u0647\u06d5\u06cc\u06d5 \u0628\u06d5 \u0647\u06d5\u0698\u0645\u0627\u0631\u06ce\u06a9\u06cc \u062a\u0631\u060c \u062f\u0627\u0648\u0627\u06cc \u06af\u06d5\u0695\u0627\u0646\u062f\u0646\u06d5\u0648\u06d5\u06cc \u0628\u06a9\u06d5 \u2014 \u062a\u06c6\u0645\u0627\u0631\u06ce\u06a9\u06cc \u062f\u0648\u0648\u06d5\u0645 \u062f\u0631\u0648\u0633\u062a \u0645\u06d5\u06a9\u06d5."},
