gakc(){return"\u0628\u06d5\u0647\u06d5\u0631\u062d\u0627\u06b5 \u062a\u06c6\u0645\u0627\u0631\u06ce\u06a9\u06cc \u0646\u0648\u06ce \u062f\u0631\u0648\u0633\u062a \u0628\u06a9\u06d5"},
