gWC(){return"\u062f\u06d5\u0631\u0648\u0627\u0632\u06d5\u06cc \u067e\u0632\u06cc\u0634\u06a9"},
gamT(){return"\u0628\u06d5\u0695\u06ce\u0648\u06d5\u0628\u0631\u062f\u0646\u06cc \u06a9\u0644\u06cc\u0646\u06cc\u06a9: \u0646\u06d5\u062e\u06c6\u0634 \u0633\u06a9\u0627\u0646 \u0628\u06a9\u06d5\u060c \u0633\u06d5\u0631\u062f\u0627\u0646\u06ce\u06a9 \u0628\u06a9\u06d5\u0631\u06d5\u0648\u06d5\u060c \u062a\u06c6\u0645\u0627\u0631\u06d5\u06a9\u06d5 \u0628\u062e\u0648\u06ce\u0646\u06d5\u0648\u06d5\u060c \u0628\u0646\u0648\u0648\u0633\u06d5\u060c \u062f\u0627\u06cc\u0628\u062e\u06d5."},
